/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}

/**
 * Applies the drizzle-kit migrations in ./drizzle to the SQLite file. Run via `pnpm db:migrate`.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import Database from "better-sqlite3";

const DEFAULT_DB_PATH = "./data/taskflow.db";
const MIGRATIONS_DIR = "./drizzle";

/**
 * Statements that bring an empty database up to the current schema.
 *
 * `drizzle-kit generate` writes SQL into `./drizzle`, and when that directory
 * exists it is authoritative. It is not checked in — the corpus has to migrate
 * offline from a clean clone — so this is the fallback "push" path, equivalent
 * to `drizzle-kit push` and kept in step with `src/server/db/schema/**`.
 */
const SCHEMA_STATEMENTS: readonly string[] = [
  `CREATE TABLE IF NOT EXISTS users (
     id TEXT PRIMARY KEY NOT NULL,
     email TEXT NOT NULL,
     name TEXT NOT NULL,
     password_hash TEXT NOT NULL,
     avatar_url TEXT,
