  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
