import { can } from \"@/lib/permissions\";
import { isArchived } from \"@/lib/soft-delete\";
import * as memberRepo from \"@/server/repositories/member-repository\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import * as recurringRepo from \"@/server/repositories/recurring-issue-repository\";
import { createIssue } from \"@/server/services/issue-service\";
import { projectResource } from \"@/server/services/_support\";
import type { Actor } from \"@/types/member\";
import type { RecurringIssue } from \"@/types/recurring-issue\";
import { runJob, type JobResult } from \"./types\";

function latestOccurrence(rule: RecurringIssue, now: Date): string | null {
  // Formatting the instant in the rule's zone accounts for DST and midnight
  // boundaries without assuming that a local day lasts 24 hours.
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone: rule.timezone, year: \"numeric\", month: \"2-digit\", day: \"2-digit\",
  }).formatToParts(now);
  const part = (type: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === type)"'!.value;
  let day = `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
  if (rule.cadence === "weekly") {
    // UTC here is only a calendar arithmetic tool, not the occurrence zone.
    const calendar = new Date(`${day}T00:00:00.000Z`);
    const weekday = calendar.getUTCDay() || 7;
    calendar.setUTCDate(calendar.getUTCDate() - (weekday - rule.weekday! + 7) % 7);
    day = calendar.toISOString().slice(0, 10);
  }
  return day < rule.startsOn ? null : day;
}

// The application has a single process/queue. Serialize overlapping sweeps so
// each one observes the occurrence checkpoint committed by its predecessor.
let previousRun: Promise<unknown> = Promise.resolve();

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  const instant = new Date(now.getTime());
  const run = previousRun.then(() => runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listUnpausedRecurringIssues();
    for (const rule of rules) {
      try {
        const occurrence = latestOccurrence(rule, instant);
        if (occurrence === null || (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn)) continue;
        const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
        if (!project || isArchived(project)) continue;

        const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
        const actor: Actor | null = creator?.status === "active"
          ? { userId: rule.createdBy, orgId: rule.orgId, role: creator.role }
          : null;
        if (!actor || !can(actor, "issue:create", projectResource(project))) {
          await recurringRepo.updateRecurringIssue(rule.orgId, rule.id, { paused: true });
          continue;
        }

        const assignee = rule.assigneeId === null ? null : await memberRepo.findMember(rule.orgId, rule.assigneeId);
        await createIssue(actor, {
          orgId: rule.orgId,
          projectId: rule.projectId,
          title: `${rule.title} (${occurrence})`,
          status: "backlog",
          priority: rule.priority,
          assigneeId: assignee?.status === "active" ? rule.assigneeId : null,
          description: null,
          dueAt: null,
          parentId: null,
          estimate: null,
          labelIds: [],
        });
        await recurringRepo.updateRecurringIssue(rule.orgId, rule.id, { lastOccurrenceOn: occurrence });
        result.processed += 1;
      } catch {
        result.failed += 1;
      }
    }
  }));
  previousRun = run.catch(() => undefined);
  return run;
}
